const normalizedIdentity = (value: any) =>
  String(value ?? '').trim().replace(/^@+/, '').toLowerCase();

const getVideoOwnerIdentities = (creator: any): string[] => {
  if (typeof creator === 'string' || typeof creator === 'number') {
    const identity = normalizedIdentity(creator);
    return identity ? [identity] : [];
  }

  const profile = creator?.profile ?? {};
  return Array.from(
    new Set(
      [
        creator?.user,
        creator?.userId,
        creator?.username,
        creator?.userName,
        creator?.backendUserId,
        creator?.mastiBaseUserId,
        creator?.accountId,
        creator?.ownerAccountId,
        creator?.creatorAccountId,
        creator?.ownerId,
        creator?.videoOwnerId,
        creator?.ownerEmail,
        creator?.email,
        creator?.userEmail,
        creator?.firebaseUid,
        creator?.authUid,
        creator?.uid,
        profile.userId,
        profile.username,
        profile.userName,
        profile.id,
        profile.mastiBaseUserId,
        profile.firebaseUid,
        profile.email,
        profile.authUid,
        profile.uid,
      ]
        .map(normalizedIdentity)
        .filter(Boolean),
    ),
  );
};

const dedupeFollowDocs = (
  docs: any[],
  role: 'follower' | 'followee',
  ownerIdentities?: Set<string>,
) => {
  const byIdentity = new Map<string, { id?: string; data: any }>();
  const duplicateDocIds: string[] = [];

  docs.forEach((docSnap: any) => {
    const docId = typeof docSnap?.id === 'string' ? docSnap.id : undefined;
    const data = typeof docSnap?.data === 'function' ? docSnap.data() : docSnap;
    if (!data || typeof data !== 'object') return;

    const followerKeys = [
      data.followerUserId,
      data.followerId,
      data.followerEmail,
      data.followerUid,
      ...(Array.isArray(data.followerAliases) ? data.followerAliases : []),
    ]
      .map(normalizedIdentity)
      .filter(Boolean);
    const followeeKeys = [
      data.followeeId,
      data.followeeBackendId,
      data.followeeEmail,
      ...(Array.isArray(data.followeeAliases) ? data.followeeAliases : []),
    ]
      .map(normalizedIdentity)
      .filter(Boolean);

    const isSelfFollow =
      followerKeys.some((fk) => followeeKeys.includes(fk)) ||
      Boolean(
        ownerIdentities &&
          ownerIdentities.size > 0 &&
          followerKeys.some((fk) => ownerIdentities.has(fk)) &&
          followeeKeys.some((tk) => ownerIdentities.has(tk)),
      );
    if (isSelfFollow) {
      if (docId) duplicateDocIds.push(docId);
      return;
    }

    const key = role === 'follower' ? followerKeys[0] : followeeKeys[0];
    if (!key) return;
    if (ownerIdentities && ownerIdentities.has(key)) {
      if (docId) duplicateDocIds.push(docId);
      return;
    }

    const existing = byIdentity.get(key);
    if (!existing) {
      byIdentity.set(key, { id: docId, data });
      return;
    }

    const existingScore =
      (existing.id && existing.id.includes('__') ? 4 : 0) +
      (existing.data?.followerPic ? 2 : 0) +
      (existing.data?.followeeName ? 1 : 0);
    const nextScore =
      (docId && docId.includes('__') ? 4 : 0) +
      (data?.followerPic ? 2 : 0) +
      (data?.followeeName ? 1 : 0);

    if (nextScore > existingScore) {
      if (existing.id) duplicateDocIds.push(existing.id);
      byIdentity.set(key, { id: docId, data });
    } else if (docId && docId !== existing.id) {
      duplicateDocIds.push(docId);
    }
  });

  return {
    records: Array.from(byIdentity.values()).map((entry) => entry.data),
    duplicateDocIds: Array.from(new Set(duplicateDocIds)),
  };
};

const isRenderableThumbnail = (uri: any) => {
  if (typeof uri !== 'string' || !uri.trim()) return false;
  const path = uri.trim().split('?')[0].toLowerCase();
  return !/\.(mp4|mov|m4v|webm|avi|mkv)(?:$|\/)/.test(path);
};

const normalizedMediaIdentity = (value: any) =>
  String(value ?? '').trim().replace(/^db-/, '').toLowerCase();

const getVideoPlaybackSource = (uri: any) => {
  const value = typeof uri === 'string' ? uri.trim() : '';
  if (!value) return null;
  const path = value.split(/[?#]/)[0];
  return /\.(mp4|mov|m4v|webm|avi|mkv|m3u8)(?:$|\/)/i.test(path)
    ? { uri: value }
    : { uri: value, overrideFileExtension: 'mp4' as const };
};

const isOwnOriginalSongPlaceholder = (song: any, videoId?: string) => {
  if (!song || typeof song !== 'object') return true;
  const titleLower = String(song.title || '').trim().toLowerCase();
  const isPlaceholderTitle = !titleLower || titleLower === 'original audio' || titleLower === 'original sound';
  if (!isPlaceholderTitle) return false;
  const audio = song.audioUrl || song.url;
  if (audio) {
    const cleanVid = String(videoId || '').replace(/^db-/, '');
    const sid = String(song.id || '');
    if (
      !sid ||
      (sid !== `original-${cleanVid}` &&
        sid !== `original_${cleanVid}` &&
        sid !== `original-${videoId}`)
    ) {
      return false;
    }
  }
  return true;
};

const shouldPlaySeparateSongAudio = (item: any) => {
  if (!item?.song) return false;
  if (typeof item.musicVol === 'number' && item.musicVol === 0) return false;
  const audio = item.song.audioUrl || item.song.url;
  if (!audio) return false;
  if (isOwnOriginalSongPlaceholder(item.song, item.id)) return false;
  if (item.song.audioMuxedInVideo || item.audioMuxedInVideo) return false;
  return true;
};

const ProfileVideoThumbnail = ({ item, coverPosition = 0 }: { item: any; coverPosition?: number }) => {
  const thumbnailUri = isRenderableThumbnail(item?.thumbnail) ? item.thumbnail : '';
  const videoRef = React.useRef<any>(null);
  const coverPositionMs = Math.max(0, Number(coverPosition) || 0) * 1000;
  const hasAddedSongThumb = Boolean(
    item?.song &&
    !isOwnOriginalSongPlaceholder(item.song, item?.id) &&
    (item.song.cover || item.musicCover)
  );
  const songThumbUri = hasAddedSongThumb ? (item.song.cover || item.musicCover) : '';
  const seekToCover = React.useCallback(() => {
    const ref = videoRef.current;
    if (!ref) return;
    try {
      const seek = ref.setPositionAsync?.(coverPositionMs);
      if (seek && typeof seek.then === 'function') {
        seek.then(() => ref.pauseAsync?.()).catch(() => {});
      } else {
        ref.pauseAsync?.();
      }
    } catch (_) {}
  }, [coverPositionMs]);

  return (
    <View style={{ flex: 1, backgroundColor: '#111', position: 'relative' }}>
      {thumbnailUri ? (
        <Image source={{ uri: thumbnailUri }} style={{ width: '100%', height: '100%', backgroundColor: '#111' }} resizeMode="cover" />
      ) : item?.url ? (
        <Video
          ref={videoRef}
          source={getVideoPlaybackSource(item.url) || undefined}
          style={{ width: '100%', height: '100%', backgroundColor: '#111' }}
          resizeMode="cover"
          shouldPlay={false}
          isLooping={false}
          isMuted
          onLoad={seekToCover}
          onReadyForDisplay={seekToCover}
          useNativeControls={false}
        />
      ) : (
        <View style={{ width: '100%', height: '100%', backgroundColor: '#111' }} />
      )}
      {songThumbUri ? (
        <View style={{
          position: 'absolute',
          bottom: 6,
          right: 6,
          width: 24,
          height: 24,
          borderRadius: 6,
          overflow: 'hidden',
          borderWidth: 1.5,
          borderColor: 'rgba(255,255,255,0.85)',
          backgroundColor: '#1c1c1e',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 2,
        }}>
          <Image
            source={{ uri: songThumbUri }}
            style={{ width: '100%', height: '100%', position: 'absolute', top: 0, left: 0 }}
            resizeMode="cover"
          />
          <View style={{
            position: 'absolute',
            inset: 0,
            backgroundColor: 'rgba(0,0,0,0.22)',
            alignItems: 'center',
            justifyContent: 'center',
          }}>
            <Ionicons name="musical-notes" size={11} color="#fff" />
          </View>
        </View>
      ) : null}
    </View>
  );
};

const SearchVideoThumbnail = ({ item }: { item: any }) => {
  const candidates = [
    item?.thumbnail,
    item?.thumbnailUrl,
    item?.thumbnail_url,
    item?.posterUrl,
  ];
  const thumbnailUri = candidates.find((uri) => isRenderableThumbnail(uri)) || '';
  const videoUrl =
    item?.url ||
    item?.videoUrl ||
    item?.fileUrl ||
    item?.mediaUrl ||
    item?.cloudinaryUrl ||
    '';
  const coverPositionMs = Math.max(0, Number(item?.coverFramePosition) || 0) * 1000;
  const videoRef = React.useRef<any>(null);

  const seekToCover = React.useCallback(() => {
    const ref = videoRef.current;
    if (!ref) return;
    try {
      const seek = ref.setPositionAsync?.(coverPositionMs);
      if (seek && typeof seek.then === 'function') {
        seek.then(() => ref.pauseAsync?.()).catch(() => {});
      } else {
        ref.pauseAsync?.();
      }
    } catch (_) {}
  }, [coverPositionMs]);

  if (thumbnailUri) {
    return (
      <Image
        source={{ uri: thumbnailUri }}
        style={{ width: '100%', height: '100%', backgroundColor: '#161618' }}
        resizeMode="cover"
      />
    );
  }

  if (videoUrl) {
    return (
      <Video
        ref={videoRef}
        source={getVideoPlaybackSource(videoUrl) || undefined}
        style={{ width: '100%', height: '100%', backgroundColor: '#161618' }}
        resizeMode="cover"
        shouldPlay={false}
        isLooping={false}
        isMuted
        onLoad={seekToCover}
        onReadyForDisplay={seekToCover}
        useNativeControls={false}
      />
    );
  }

  return (
    <View style={{ flex: 1, backgroundColor: '#161618', alignItems: 'center', justifyContent: 'center' }}>
      <Ionicons name="play" size={26} color="#666" />
    </View>
  );
};

const formatSearchCount = (rawValue: any) => {
  const n = Math.max(0, Number(rawValue) || 0);
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`;
  }
  if (n >= 10_000) {
    return `${(n / 1_000).toFixed(1).replace(/\.0$/, '')}K`;
  }
  return String(Math.round(n));
};

const formatSearchDateLabel = (item: any) => {
  const rawDate =
    item?.createdAt ??
    item?.created_at ??
    item?.uploadedAt ??
    item?.uploaded_at ??
    item?.publishedAt ??
    item?.published_at ??
    item?.timestamp;
  if (rawDate) {
    const parsed = new Date(rawDate);
    if (!Number.isNaN(parsed.getTime())) {
      return `${parsed.getMonth() + 1}.${String(parsed.getDate()).padStart(2, '0')}`;
    }
  }
  if (item?.duration) {
    return String(item.duration);
  }
  return '';
};

const renderSearchCaption = (rawText: string) => {
  const text = String(rawText || '').trim();
  if (!text) return null;
  const parts = text.split(/(#[^\s#]+|@[^\s@]+)/g);
  return (
    <Text
      numberOfLines={2}
      style={{ fontSize: 13.5, lineHeight: 18, color: '#e5e5ea', fontWeight: '400' }}
    >
      {parts.map((part, idx) => {
        const isToken = part.startsWith('#') || part.startsWith('@');
        return (
          <Text
            key={idx}
            style={isToken ? { color: '#ffffff', fontWeight: '700' } : undefined}
          >
            {part}
          </Text>
        );
      })}
    </Text>
  );
};

const AudioEqualizerBars = ({ isPlaying }: { isPlaying: boolean }) => {
  const bar1 = React.useRef(new Animated.Value(0.45)).current;
  const bar2 = React.useRef(new Animated.Value(0.9)).current;
  const bar3 = React.useRef(new Animated.Value(0.6)).current;

  React.useEffect(() => {
    if (!isPlaying) {
      bar1.stopAnimation();
      bar2.stopAnimation();
      bar3.stopAnimation();
      bar1.setValue(0.42);
      bar2.setValue(0.78);
      bar3.setValue(0.55);
      return;
    }

    const loopBar = (val: Animated.Value, toMax: number, toMin: number, dur: number) =>
      Animated.loop(
        Animated.sequence([
          Animated.timing(val, { toValue: toMax, duration: dur, useNativeDriver: false }),
          Animated.timing(val, { toValue: toMin, duration: dur, useNativeDriver: false }),
        ]),
      );

    const a1 = loopBar(bar1, 1.0, 0.25, 300);
    const a2 = loopBar(bar2, 0.3, 1.0, 260);
    const a3 = loopBar(bar3, 0.95, 0.28, 340);
    a1.start();
    a2.start();
    a3.start();

    return () => {
      a1.stop();
      a2.stop();
      a3.stop();
    };
  }, [isPlaying, bar1, bar2, bar3]);

  const maxH = 14;
  return (
    <View
      style={{
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        height: 16,
        gap: 2.5,
        marginRight: 7,
      }}
    >
      {[bar1, bar2, bar3].map((animVal, idx) => (
        <Animated.View
          key={idx}
          style={{
            width: 3,
            borderRadius: 1.5,
            backgroundColor: '#dbeafe',
            height: animVal.interpolate({
              inputRange: [0, 1],
              outputRange: [3, maxH],
            }),
          }}
        />
      ))}
    </View>
  );
};

// expo-av can reject when a video is unmounted while a playback command is
// still in flight (notably when navigating from feed to a profile). These
// commands are best-effort and must not surface as unhandled native errors.
const safeMediaCall = (ref: any, method: string, ...args: any[]) => {
  try {
    const result = ref?.[method]?.(...args);
    if (result && typeof result.catch === 'function') {
      result.catch(() => {});
    }
  } catch (_) {}
};

